import{_ as p,a0 as o,w as r,s as d,ao as l,I as e,x as n,a1 as i,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Zsync：一個僅下載文件新的部分的傳輸工具 | LCTT x X-CMD","titleTemplate":false,"description":"Zsync：一個僅下載文件新的部分的傳輸工具 | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Zsync：一個僅下載文件新的部分的傳輸工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Zsync：一個僅下載文件新的部分的傳輸工具 | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20180205 A File Transfer Utility To Download Only The New Parts Of A File","title":"Zsync：一個僅下載文件新的部分的傳輸工具","tag":"201803","desc":""},"relativePath":"201803/20180205 A File Transfer Utility To Download Only The New Parts Of A File.md","filePath":"[post].md"}'),c={name:"201803/20180205 A File Transfer Utility To Download Only The New Parts Of A File.md"};function h(g,s,u,y,k,b){const t=o("Link");return r(),d("div",null,[s[16]||(s[16]=l('<h1 id="zsync-一個僅下載文件新的部分的傳輸工具" tabindex="-1">Zsync：一個僅下載文件新的部分的傳輸工具 <a class="header-anchor" href="#zsync-一個僅下載文件新的部分的傳輸工具" aria-label="Permalink to “Zsync：一個僅下載文件新的部分的傳輸工具”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/02/Linux-1-720x340.png" alt=""></p><p>就算是網費每天變得越來越便宜，你也不應該重複下載相同的東西來浪費你的流量。一個很好的例子就是下載 Ubuntu 或任何 Linux 鏡像的開發版本。如你所知，Ubuntu 開發人員每隔幾個月就會發布一次日常構建、alpha、beta 版 ISO 鏡像以供測試。在過去，一旦發佈我就會下載這些鏡像，並審查每個版本。現在不用了！感謝 Zsync 文件傳輸程序。現在可以僅下載 ISO 鏡像新的部分。這將為你節省大量時間和 Internet 帶寬。不僅時間和帶寬，它將為你節省服務端和客户端的資源。</p><p>Zsync 使用與 Rsync 相同​​的算法，如果你會得到一份已有文件舊版本，它只下載該文件新的部分。 Rsync 主要用於在計算機之間同步數據，而 Zsync 則用於分發數據。簡單地説，可以使用 Zsync 將中心的一個文件分發給數千個下載者。它在 Artistic License V2 許可證下發布，完全免費且開源。</p><h3 id="安裝-zsync" tabindex="-1">安裝 Zsync <a class="header-anchor" href="#安裝-zsync" aria-label="Permalink to “安裝 Zsync”">​</a></h3><p>Zsync 在大多數 Linux 發行版的默認倉庫中有。</p><p>在 Arch Linux 及其衍生版上，使用命令安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S zsync</span></span></code></pre></div><p>在 Fedora 上，啓用 Zsync 倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf copr enable ngompa/zsync</span></span></code></pre></div><p>並使用命令安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install zsync</span></span></code></pre></div><p>在 Debian、Ubuntu、Linux Mint 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install zsync</span></span></code></pre></div>',14)),e("p",null,[s[1]||(s[1]=n("對於其他發行版，你可以從 ",-1)),i(t,{href:"http://zsync.moria.org.uk/downloads"},{default:a(()=>[...s[0]||(s[0]=[n("Zsync 下載頁面",-1)])]),_:1}),s[2]||(s[2]=n("下載二進制打包文件，並手動編譯安裝它，如下所示。",-1))]),s[17]||(s[17]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget http://zsync.moria.org.uk/download/zsync-0.6.2.tar.bz2</span></span>
<span class="line"><span>$ tar xjf zsync-0.6.2.tar.bz2</span></span>
<span class="line"><span>$ cd zsync-0.6.2/</span></span>
<span class="line"><span>$ configure</span></span>
<span class="line"><span>$ make</span></span>
<span class="line"><span>$ sudo make install</span></span></code></pre></div><h3 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to “用法”">​</a></h3><p>請注意，只有當人們提供 zsync 下載方式時，zsync 才有用。目前，Debian、Ubuntu（所有版本）的 ISO 鏡像都有 .zsync 下載鏈接。例如，請訪問以下鏈接。</p><p>你可能注意到，Ubuntu 18.04 LTS 每日構建版有直接的 ISO 和 .zsync 文件。如果你下載 .ISO 文件，則必須在 ISO 更新時下載完整的 ISO 文件。但是，如果你下載的是 .zsync 文件，那麼 Zsync 以後僅會下載新的更改。你不需要每次都下載整個 ISO 映像。</p><p>.zsync 文件包含 zsync 程序所需的元數據。該文件包含 rsync 算法的預先計算的校驗和。它在服務器上生成一次，然後由任意數量的下載器使用。要使用 Zsync 客户端程序下載 .zsync 文件，你只需執行以下操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ zsync &lt;.zsync-file-URL&gt;</span></span></code></pre></div><p>例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ zsync http://cdimage.ubuntu.com/ubuntu/daily-live/current/bionic-desktop-amd64.iso.zsync</span></span></code></pre></div><p>如果你的系統中已有以前的鏡像文件，那麼 Zsync 將計算遠程服務器中舊文件和新文件之間的差異，並僅下載新的部分。你將在終端看見計算過程一系列的點或星星。</p><p>如果你下載的文件的舊版本存在於當前工作目錄，那麼 Zsync 將只下載新的部分。下載完成後，你將看到兩個鏡像，一個你剛下載的鏡像和以 .iso.zs-old 為擴展名的舊鏡像。</p><p>如果沒有找到相關的本地數據，Zsync 會下載整個文件。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/02/Zsync-1.png" alt=""></p><p>你可以隨時按 <code>CTRL-C</code> 取消下載過程。</p><p>試想一下，如果你直接下載 .ISO 文件或使用 torrent，每當你下載新鏡像時，你將損失約 1.4GB 流量。因此，Zsync 不會下載整個 Alpha、beta 和日常構建映像，而只是在你的系統上下載了 ISO 文件的新部分，並在系統中有一箇舊版本的拷貝。</p><p>今天就到這裏。希望對你有幫助。我將很快另外寫一篇有用的指南。在此之前，請保持關注！</p><p>乾杯！</p><hr>`,17)),e("p",null,[s[4]||(s[4]=n("via: ",-1)),i(t,{href:"https://www.ostechnix.com/zsync-file-transfer-utility-download-new-parts-file/"},{default:a(()=>[...s[3]||(s[3]=[n("https://www.ostechnix.com/zsync-file-transfer-utility-download-new-parts-file/",-1)])]),_:1})]),e("p",null,[s[8]||(s[8]=n("作者：",-1)),i(t,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>[...s[5]||(s[5]=[n("SK",-1)])]),_:1}),s[9]||(s[9]=n(" 譯者：",-1)),i(t,{href:"https://github.com/geekpi"},{default:a(()=>[...s[6]||(s[6]=[n("geekpi",-1)])]),_:1}),s[10]||(s[10]=n(" 校對：",-1)),i(t,{href:"https://github.com/wxy"},{default:a(()=>[...s[7]||(s[7]=[n("wxy",-1)])]),_:1})]),e("p",null,[s[13]||(s[13]=n("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[11]||(s[11]=[n("LCTT",-1)])]),_:1}),s[14]||(s[14]=n(" 原創編譯，",-1)),i(t,{href:"https://linux.cn/"},{default:a(()=>[...s[12]||(s[12]=[n("Linux中國",-1)])]),_:1}),s[15]||(s[15]=n(" 榮譽推出",-1))])])}const w=p(c,[["render",h]]);export{T as __pageData,w as default};
